import {phases,addonNotes,featured,sources} from './guide.js';
import {createEngine,clampCount,cleanState} from './engine.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('es-MX',{maximumFractionDigits:2}).format(n);
const key='brassbound:atm10:8.1:v1';
const initial={schema:1,tasks:{},inventory:{},mods:{},notes:'',plans:[],preferences:{},selections:{}};
let state=structuredClone(initial),storageError=false;
try{const saved=localStorage.getItem(key);if(saved)state=cleanState(JSON.parse(saved));}catch{storageError=true;}
let recipes=[],translations={},tags={},icons={},addons=[],pack={},mods=[],report={},stress={},engine,view='home',recipeQuery='',recipeScope='featured',recipeMod='all',recipePage=0,modScope='addons',modQuery='',routeScope='create',plannerItem='create:mechanical_press',plannerQuantity=1,plannerRecipe='',plannerExpand=true,currentPlan=null;
const views=[['home','⌂','Vista general'],['routes','⌘','Ruta de progreso'],['recipes','▦','Recetario'],['planner','⌁','Planos de fabricación'],['inventory','▤','Mis materiales'],['mods','◈','Explorar mods'],['notes','▧','Mi bitácora']];
const types={'minecraft:crafting_shaped':'Mesa de crafteo','minecraft:crafting_shapeless':'Crafteo sin forma','minecraft:smelting':'Horno','minecraft:blasting':'Alto horno','minecraft:smoking':'Ahumador','minecraft:campfire_cooking':'Hoguera','minecraft:stonecutting':'Cortapiedras','minecraft:smithing_transform':'Mesa de herrería','create:item_application':'Aplicación manual','create:mixing':'Mezclador + cubeta','create:pressing':'Prensa mecánica','create:compacting':'Prensa + cubeta','create:cutting':'Sierra mecánica','create:crushing':'Ruedas de trituración','create:milling':'Molino','create:deploying':'Desplegador','create:sequenced_assembly':'Ensamblaje secuenciado','create:filling':'Llenado con surtidor','create:emptying':'Desagüe','create:splashing':'Ventilador + agua','create:haunting':'Ventilador + fuego de almas','create:mechanical_crafting':'Crafters mecánicos','create:sandpaper_polishing':'Papel de lija','createaddition:rolling':'Laminadora','createaddition:charging':'Carga eléctrica','create_enchantment_industry:infusing':'Infuser','create_enchantment_industry:grinding':'Trituración de experiencia','create_aquatic_ambitions:channeling':'Canalización','create_dragons_plus:freezing':'Congelación','create_dragons_plus:ending':'Procesamiento del End','atm:kubejs':'Receta de ATM10'};
const manualNames={'create:andesite_alloy':'Aleación de andesita','create:mechanical_press':'Prensa mecánica','create:water_wheel':'Rueda hidráulica','create:precision_mechanism':'Mecanismo de precisión','create:brass_ingot':'Lingote de latón','create:andesite_casing':'Carcasa de andesita','create:brass_casing':'Carcasa de latón','create:shaft':'Eje','create:cogwheel':'Engranaje pequeño','create:large_cogwheel':'Engranaje grande','create:depot':'Depósito','create:mechanical_mixer':'Mezclador mecánico','create:basin':'Cubeta','create:steam_engine':'Motor de vapor','create:track':'Vía de tren','create:rotation_speed_controller':'Controlador de velocidad','create:crushing_wheel':'Rueda de trituración','create:mechanical_arm':'Brazo mecánico','create:packager':'Empaquetador','create:stock_link':'Enlace de inventario','createaddition:electric_motor':'Motor eléctrico','createaddition:alternator':'Alternador','create:wrench':'Llave inglesa','create:golden_sheet':'Lámina de oro','create:iron_sheet':'Lámina de hierro','create:copper_sheet':'Lámina de cobre','create:brass_sheet':'Lámina de latón','create:empty_blaze_burner':'Quemador de blaze vacío','create:deployer':'Desplegador','create:mechanical_crafter':'Crafter mecánico','create:belt_connector':'Correa mecánica','create:millstone':'Molino','create:encased_fan':'Ventilador encapsulado'};
function name(id){if(manualNames[id])return manualNames[id];if(id.startsWith('#'))return 'Cualquier '+id.slice(1).split(':').pop().replaceAll('/',' · ').replaceAll('_',' ');const [ns,part]=id.split(':');const base=part||ns;return translations.es_es?.[`item.${ns}.${base}`]||translations.es_es?.[`block.${ns}.${base}`]||translations.en_us?.[`item.${ns}.${base}`]||translations.en_us?.[`block.${ns}.${base}`]||base.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());}
function engName(id){const [ns,part]=id.split(':');return translations.en_us?.[`item.${ns}.${part}`]||translations.en_us?.[`block.${ns}.${part}`]||id;}
function icon(id){const url=icons[id];return url?`<img class="item-icon" src="${esc(url)}" alt="" loading="lazy" onerror="this.style.visibility='hidden'">`:`<span class="item-fallback" aria-hidden="true">${id.includes('fluid')?'◒':id.includes('ingot')||id.includes('sheet')?'▱':id.includes('cog')?'⚙':'◇'}</span>`;}
function process(type){return types[type]||type.split(':').pop().replaceAll('_',' ');}
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageError=false;}catch{storageError=true;toast('No se pudo guardar. Exporta un respaldo de tu bitácora.');}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function completed(phase){return phase.tasks.filter(t=>state.tasks[phase.id+':'+t[0]]).length;}
function totalDone(){return phases.reduce((n,p)=>n+completed(p),0);}
function totalTasks(){return phases.reduce((n,p)=>n+p.tasks.length,0);}
function currentPhase(){return phases.find(p=>completed(p)<p.tasks.length)||phases.at(-1);}
function percent(){return Math.round(totalDone()/totalTasks()*100);}
function pageTitle(eyebrow,title,description,action=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function nav(){ $('#main-nav').innerHTML=views.map(([id,icon,label])=>`<button class="nav-button ${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}${id==='notes'&&state.plans.length?`<span class="count">${state.plans.length}</span>`:''}</button>`).join('');$('#breadcrumb-current').textContent=views.find(v=>v[0]===view)?.[2]||'Fuentes y versión';}
function render(){nav();$('#content').innerHTML=({home:homeView,routes:routesView,recipes:recipesView,planner:plannerView,inventory:inventoryView,mods:modsView,notes:notesView,sources:sourcesView}[view]||homeView)();}
function navigate(next){view=views.some(v=>v[0]===next)||next==='sources'?next:'home';history.replaceState(null,'','#'+view);$('.sidebar').classList.remove('open');render();window.scrollTo({top:0});}
function homeView(){const cur=currentPhase();const num=phases.indexOf(cur)+1;return `<section class="hero"><div class="hero-copy"><div class="eyebrow">TU MUNDO. TUS MÁQUINAS. TU RITMO.</div><h1>Todo gran imperio<br>empieza <em>con un giro.</em></h1><p>De tu primera rueda hidráulica a una fábrica que trabaja sola. Aquí empieza tu historia con Create.</p><button class="btn btn-primary" data-phase="${cur.id}">${totalDone()?'Continuar mi ruta':'Construir mi primer taller'} <span>↗</span></button></div><img class="hero-art" src="assets/workshop.svg" alt="Plano isométrico de un taller con rueda hidráulica, prensa, depósito y correa"><div class="hero-tag"><span>CREATE 6.0.10</span><span>•</span><span>EDICIÓN ATM10 8.1</span></div></section>
<section class="stats-grid" aria-label="Resumen de tu taller"><div class="stat"><div class="stat-label">Tu progreso en Create</div><span class="stat-symbol">⌁</span><div class="stat-value">${percent()}<small>% completado</small></div><div class="mini-bar"><span style="width:${percent()}%"></span></div></div><div class="stat"><div class="stat-label">Objetivos completados</div><span class="stat-symbol">☑</span><div class="stat-value">${totalDone()}<small>/ ${totalTasks()}</small></div><small class="muted">Cada pequeño paso cuenta</small></div><div class="stat"><div class="stat-label">Planos en tu bitácora</div><span class="stat-symbol">▧</span><div class="stat-value">${state.plans.length.toString().padStart(2,'0')}<small>guardados</small></div><small class="muted">Tu próxima gran construcción</small></div><div class="stat"><div class="stat-label">Tu siguiente etapa</div><span class="stat-symbol">↗</span><div class="stat-value">${String(num).padStart(2,'0')}<small>/ 08</small></div><small class="muted">${cur.name}</small></div></section>
<div class="dashboard-columns"><section><div class="section-heading"><div><h2>El camino del ingeniero</h2><p>Una ruta clara. Un descubrimiento a la vez.</p></div><button class="btn btn-text" data-view="routes">Ver ruta completa ↗</button></div><div class="panel route-preview">${phases.slice(0,4).map((p,i)=>`<div class="route-row ${p.id===cur.id?'current':''} ${completed(p)===p.tasks.length?'done':''}"><span class="step-number">${completed(p)===p.tasks.length?'✓':String(i+1).padStart(2,'0')}</span><div class="row-copy"><h4>${p.name}</h4><p>${p.subtitle}</p></div>${p.id===cur.id?'<span class="badge gold">ESTÁS AQUÍ</span>':completed(p)===p.tasks.length?'<span class="badge">COMPLETADO</span>':'<span class="row-arrow">↗</span>'}<button data-phase="${p.id}" aria-label="Abrir etapa ${p.name}"></button></div>`).join('')}</div></section><section><div class="section-heading"><div><h2>Tu siguiente paso</h2><p>Menos ruido. Más construir.</p></div><span class="badge gold">RECOMENDADO</span></div><div class="panel next-card"><div class="panel-body"><div class="next-icon">${cur.icon}</div><h3>${cur.id==='prepare'?'Un lugar para empezar.':cur.name}</h3><p>${cur.id==='prepare'?'Antes de las máquinas, prepara tu espacio. Reúne los materiales esenciales y conoce las herramientas que te acompañarán.':cur.description}</p><button class="btn btn-secondary" data-phase="${cur.id}">Abrir objetivos <span>→</span></button></div></div><div class="tip"><span>☼</span><p>No tienes que aprender todos los mods hoy.<br>Una buena fábrica empieza entendiendo una máquina.</p></div></section></div>
<section class="quick-mods"><div class="section-heading"><div><h2>Un universo que se conecta</h2><p>Haz crecer tu taller con los mods adecuados.</p></div><button class="btn btn-text" data-view="mods">Explorar mods ↗</button></div><div class="mod-mini-grid">${[['CR','Create','Movimiento e imaginación','create'],['CA','Crafts & Additions','Del giro a la electricidad','createaddition'],['AE','Applied Energistics 2','Todo en su lugar','ae2'],['MK','Mekanism','Procesa a otra escala','mekanism']].map(([code,label,sub,id])=>`<button class="mod-mini" data-mod-detail="${id}"><span class="mod-initial">${code}</span><span><strong>${label}</strong><small>${sub}</small></span></button>`).join('')}</div></section>${storageError?'<p class="server-note">El almacenamiento local no está disponible. Exporta tu avance desde Mi bitácora.</p>':''}`;}
function routesView(){return pageTitle('UN OBJETIVO A LA VEZ','Tu ruta de progreso','Empieza por Create; abre otra rama cuando resuelva una necesidad de tu taller. El orden es una recomendación, no un bloqueo del pack.')+`<div class="toolbar"><div class="tabs"><button class="tab ${routeScope==='create'?'active':''}" data-route-scope="create">Create · 8 etapas</button><button class="tab ${routeScope==='pack'?'active':''}" data-route-scope="pack">Otros mods · ${pack.routes.length} rutas</button><button class="tab ${routeScope==='star'?'active':''}" data-route-scope="star">La ATM Star</button></div><span class="list-count">${routeScope==='create'?`${totalDone()} de ${totalTasks()} objetivos`:routeScope==='pack'?'Ramas complementarias':'Endgame del pack 8.1'}</span></div>`+(routeScope==='create'?`<div class="phase-grid">${phases.map((p,i)=>`<article class="phase-card ${p.id===currentPhase().id?'current':''}"><div class="phase-card-head"><span class="step-number">${String(i+1).padStart(2,'0')}</span><div><div class="eyebrow" style="font-size:8px">${p.level}</div><h3>${p.name}</h3><p>${p.subtitle}</p><div class="phase-tags"><span class="badge ${p.id===currentPhase().id?'gold':'muted'}">${completed(p)===p.tasks.length?'COMPLETADO':p.id===currentPhase().id?'SIGUIENTE ETAPA':'A TU RITMO'}</span></div></div></div><div class="phase-card-bottom"><span>${completed(p)} / ${p.tasks.length} objetivos</span><button class="btn btn-text" data-phase="${p.id}">Explorar etapa →</button></div></article>`).join('')}</div>`:routeScope==='pack'?`<div class="phase-grid">${pack.routes.map((r,i)=>{const done=r.steps.filter(t=>state.tasks['pack:'+t.id]).length;return `<article class="phase-card"><div class="phase-card-head"><span class="step-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(r.name)}</h3><p>${esc(r.purpose)}</p><div class="phase-tags">${r.mods.slice(0,3).map(m=>`<span class="badge muted">${esc(m)}</span>`).join('')}</div></div></div><div class="phase-card-bottom"><span>${done} / ${r.steps.length} objetivos</span><button class="btn btn-text" data-pack-route="${r.id}">Abrir ruta →</button></div></article>`;}).join('')}</div>`:starView());}
function starView(){const r=pack.starRecipe;return `<div class="two-col"><div class="stack"><div class="panel"><div class="panel-header"><span class="next-icon">✧</span><div><h3>ATM Star · Runic Star Altar</h3><p>La receta final de la versión 8.1</p></div></div><div class="panel-body"><div class="note-box"><strong>La estrella se fabrica en el Star Altar de Modern Industrialization.</strong><br>${esc(r.note)}</div><div class="planner-summary"><span><b>${fmt(r.euPerTick)}</b> EU/t</span><span><b>${r.ticks}</b> ticks de receta</span><span>Infraestructura + ${r.inputs.length} entradas</span></div><ul class="checklist">${r.inputs.map((i,n)=>`<li class="check-item ${state.tasks['star:'+n]?'completed':''}"><input type="checkbox" id="star-${n}" data-task="star:${n}" ${state.tasks['star:'+n]?'checked':''}><label for="star-${n}">${fmt(i.count)} × ${esc(i.name)}${i.components?`<small>Componentes obligatorios: ${esc(i.components)}</small>`:''}</label></li>`).join('')}</ul><a class="btn btn-text" href="${esc(r.source)}" target="_blank" rel="noopener noreferrer">Consultar receta oficial ↗</a></div></div>${pack.starAltarBuild?`<div class="panel"><div class="panel-header"><h3>Construir el altar</h3></div><div class="panel-body"><p class="muted" style="font-size:12px">El altar es una estructura multibloque. Consulta la definición del pack y la vista previa dentro del juego para orientación, bloques y hatches.</p><details class="disclosure"><summary>Ver desglose de construcción investigado</summary><pre class="raw-json">${esc(JSON.stringify(pack.starAltarBuild,null,2))}</pre></details></div></div>`:''}</div><div class="stack"><div class="panel"><div class="panel-header"><h3>Las piezas del endgame</h3></div><div class="panel-body">${pack.starComponents.map(s=>`<details class="disclosure"><summary>${esc(s.name)}</summary><p>${esc(s.goal)}</p><div class="phase-tags">${s.mods.map(m=>`<span class="badge muted">${esc(m)}</span>`).join('')}</div><a class="btn btn-text" href="${esc(s.source)}" target="_blank" rel="noopener noreferrer">Fuente de componentes ↗</a></details>`).join('')}</div></div><div class="note-box">Marca recursos cuando los tengas preparados. La web no lee tu inventario del servidor.</div></div></div>`;}
function phaseDialog(id){const p=phases.find(x=>x.id===id);if(!p)return;const n=phases.indexOf(p);showDialog(`${String(n+1).padStart(2,'0')} / ${p.name}`,p.level,`<p>${p.description}</p><h3>Objetivos de esta etapa</h3><ul class="checklist">${p.tasks.map(t=>{const k=p.id+':'+t[0];return `<li class="check-item ${state.tasks[k]?'completed':''}"><input type="checkbox" id="task-${t[0]}" data-task="${k}" ${state.tasks[k]?'checked':''}><label for="task-${t[0]}">${t[1]}<small>${t[2]}</small></label></li>`;}).join('')}</ul><h3>Componentes que vas a conocer</h3><div class="recipe-process">${p.items.map(item=>`<button class="ingredient-chip" data-item="${item}">${icon(item)}${esc(name(item))}</button>`).join('')}</div><div class="note-box">${p.tip}</div><p class="server-note">Guía editorial basada en recetas de Create 6.0.10 y misiones de ATM10 8.1. Consulta la receta activa en JEI.</p>${n<phases.length-1?`<button class="btn btn-secondary" data-phase="${phases[n+1].id}">Ver la siguiente etapa →</button>`:''}`);}
function packRouteDialog(id){const r=pack.routes.find(x=>x.id===id);if(!r)return;showDialog(r.name,'RUTA COMPLEMENTARIA · ATM10 8.1',`<p>${esc(r.purpose)}</p><div class="phase-tags">${Object.entries(r.modVersions||{}).map(([k,v])=>`<span class="badge">${esc(k)} ${esc(v)}</span>`).join('')}</div><h3>Plan de trabajo</h3><ul class="checklist">${r.steps.map(t=>{const k='pack:'+t.id;return `<li class="check-item ${state.tasks[k]?'completed':''}"><input type="checkbox" id="${esc(t.id)}" data-task="${esc(k)}" ${state.tasks[k]?'checked':''}><label for="${esc(t.id)}">${esc(t.title)}<small>${esc(t.detail)}</small>${t.requires.length?`<small>Antes: ${t.requires.map(req=>esc(r.steps.find(s=>s.id===req)?.title||req)).join(' · ')}</small>`:''}</label></li>`;}).join('')}</ul><p class="server-note">${esc(r.ordering)}</p><h3>Fuentes</h3>${r.sources.map((url,i)=>`<a class="btn btn-text" target="_blank" rel="noopener noreferrer" href="${esc(url)}">${i+1}. Misiones / scripts del pack ↗</a><br>`).join('')}`);}
function filteredRecipes(){let list=recipes.filter(r=>r.output?.id);if(recipeScope==='featured')list=featured.map(id=>engine.choose(id)).filter(Boolean);else if(recipeScope==='create')list=list.filter(r=>r.source.modId!=='minecraft'&&!r.id.startsWith('atm-guide:'));else if(recipeScope==='pack')list=list.filter(r=>r.id.startsWith('atm-guide:'));if(recipeMod!=='all')list=list.filter(r=>r.source.modId===recipeMod);const q=recipeQuery.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');if(q)list=list.filter(r=>(name(r.output.id)+' '+engName(r.output.id)+' '+r.output.id+' '+r.id+' '+process(r.type)).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q));return list;}
function recipesView(){const list=filteredRecipes();const size=24;recipePage=Math.min(recipePage,Math.max(0,Math.ceil(list.length/size)-1));return pageTitle('DEL RECURSO A LA MÁQUINA','El recetario del taller','Busca en español, en inglés o por ID. Revisa ingredientes, procesos, alternativas y la fuente exacta de cada receta.')+`<div class="toolbar"><input id="recipe-search" type="search" placeholder="Prensa, precision mechanism, create:shaft…" value="${esc(recipeQuery)}" aria-label="Buscar recetas"><select id="recipe-mod" aria-label="Filtrar por mod"><option value="all">Todos los mods del catálogo</option>${addons.map(m=>`<option value="${m.modId}" ${recipeMod===m.modId?'selected':''}>${esc(m.name)}</option>`).join('')}<option value="minecraft" ${recipeMod==='minecraft'?'selected':''}>Minecraft</option><option value="atm10" ${recipeMod==='atm10'?'selected':''}>ATM10 · selección KubeJS</option></select></div><div class="toolbar"><div class="tabs">${[['featured','Primeros pasos'],['create','Create + addons'],['pack','Especiales de ATM10'],['all','Todo el catálogo']].map(([id,n])=>`<button class="tab ${recipeScope===id?'active':''}" data-recipe-scope="${id}">${n}</button>`).join('')}</div><span class="list-count">${fmt(list.length)} recetas</span></div><div class="note-box" style="margin-bottom:20px">Catálogo de recursos estáticos fijado a 8.1; incluye alternativas y recetas de compatibilidad. JEI del servidor confirma cambios de KubeJS, unificación de metales y componentes dinámicos.</div><div id="recipe-results">${list.length?`<div class="recipe-grid">${list.slice(recipePage*size,(recipePage+1)*size).map(r=>recipeCard(r)).join('')}</div><div class="pagination"><button class="btn btn-small" data-page="${recipePage-1}" ${recipePage===0?'disabled':''}>← Anterior</button><span>${recipePage+1} / ${Math.ceil(list.length/size)}</span><button class="btn btn-small" data-page="${recipePage+1}" ${(recipePage+1)*size>=list.length?'disabled':''}>Siguiente →</button></div>`:'<div class="empty-state"><h3>Aún no hay una receta con ese filtro.</h3><p>Prueba su nombre en inglés, el ID del objeto o cambia a Todo el catálogo.</p></div>'}</div>`;}
function recipeCard(r){return `<article class="recipe-card"><div class="item-line">${icon(r.output.id)}<div><h3>${esc(name(r.output.id))}</h3><small>${esc(r.source.modId)}</small></div></div><span class="badge ${r.certainty==='atm-override'?'gold':'muted'}">${esc(process(r.type))}</span><div class="recipe-meta"><span class="pill-count">${fmt(r.output.count)} ${r.output.kind==='fluid'?'mB':'unidad'+(r.output.count!==1?'es':'')}${r.output.chance<1?` · ${fmt(r.output.chance*100)} %`:''}</span><button class="btn btn-text" data-recipe="${esc(r.id)}">Ver receta ↗</button></div></article>`;}
function showDialog(title,sub,body){$('#dialog-content').innerHTML=`<div class="dialog-header"><div><h2>${esc(title)}</h2><small>${esc(sub)}</small></div><button class="icon-button" data-close aria-label="Cerrar ventana">✕</button></div><div class="dialog-body">${body}</div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0;}
function recipeDialog(id){const r=engine.byId.get(id);if(!r)return;const pattern=r.raw?.pattern;const sourceUrl=r.source.url;showDialog(name(r.output.id),`${process(r.type)} · ${r.source.version||'ATM10 8.1'}`,`<div class="recipe-process">${r.ingredients.map(i=>{const resolved=engine.resolve(i,state.selections);return `<div class="ingredient-chip">${icon(resolved.id)}<span>${fmt(i.count)} ${i.kind==='fluid'?'mB de':'×'} ${esc(name(resolved.id))}${i.kind==='tag'?`<small class="muted" style="display:block">Alternativa: #${esc(i.id)}</small>`:''}</span></div>`;}).join('')}<span class="process-arrow">→</span><div class="ingredient-chip">${icon(r.output.id)}<span>${fmt(r.output.count)} ${r.output.kind==='fluid'?'mB de':'×'} ${esc(name(r.output.id))}</span></div></div>${pattern?`<details class="disclosure" open><summary>Patrón de fabricación</summary><div class="craft-grid" style="--cols:${Math.max(...pattern.map(x=>x.length))}">${pattern.join('').split('').map(c=>{const ing=r.raw.key?.[c];const item=ing?.item||ing?.id||(ing?.tag?engine.resolve({id:ing.tag,kind:'tag'},state.selections).id:null);return `<div class="craft-cell" title="${item?esc(name(item)):''}">${item?icon(item):c.trim()?'<span title="Consulta la clave en los datos originales">'+esc(c)+'</span>':''}</div>`;}).join('')}</div></details>`:''}${r.sequence?`<h3>Secuencia · ${r.loops||1} ciclo${r.loops!==1?'s':''}</h3><ol class="sequence-list">${r.sequence.map(s=>`<li>${esc(process(s.type))}: ${s.ingredients.map(i=>`${i.count} × ${esc(name(engine.resolve(i,state.selections).id))}`).join(', ')||'operación sin ingrediente añadido'}</li>`).join('')}</ol><p>La lista de materiales superior ya incluye todos los ciclos.</p>`:''}${r.heat?`<div class="note-box">${r.heat==='superheated'?'Requiere sobrecalentamiento.':'Requiere calor: quemador de blaze activo bajo la cubeta.'}</div>`:''}${r.output.chance<1?`<div class="note-box mt"><strong>Resultado aleatorio: ${fmt(r.output.chance*100)} % de éxito por intento.</strong><br>Los materiales no garantizan una cantidad final. La calculadora presenta una estimación media.</div>`:''}${r.outputs.length>1?`<details class="disclosure"><summary>Salidas y probabilidades</summary><p>${r.outputs.map(o=>`${o.count} × ${esc(name(o.id))}${o.chance<1?' · '+fmt(o.chance*100)+' %':''}`).join('<br>')}</p></details>`:''}${r.raw?.sourceCost||r.raw?.source_cost||r.sourceCost?`<div class="note-box mt">Coste de Source: ${fmt(r.sourceCost||r.raw.sourceCost||r.raw.source_cost)}. Prepara el sistema de Ars por separado.</div>`:''}${r.experienceCost?`<div class="note-box mt">Experiencia requerida: ${fmt(r.experienceCost)}. Verifica cómo se expresa este coste en el proceso del addon.</div>`:''}${r.warnings?.length?`<div class="note-box mt">${r.warnings.map(esc).join('<br>')}</div>`:''}<div class="gap-row"><button class="btn btn-primary" data-plan="${esc(r.output.id)}" data-plan-recipe="${esc(r.id)}">Calcular materiales ↗</button><button class="btn" data-inventory-add="${esc(r.output.id)}">Añadir 1 a mis materiales</button></div><details class="disclosure mt"><summary>Fuente y datos de la receta</summary><p>${esc(r.source.jar||'KubeJS de ATM10 8.1')}<br>${esc(r.source.path||r.id)}</p>${sourceUrl?`<a class="btn btn-text" href="${esc(sourceUrl)}" target="_blank" rel="noopener noreferrer">Consultar archivo de origen ↗</a>`:''}<pre class="raw-json">${esc(JSON.stringify(r.raw,null,2))}</pre></details><p class="server-note">Las alternativas de materiales se pueden ajustar en el plano. Las herramientas, combustibles y máquinas de proceso se preparan aparte.</p>`);}
function itemDialog(id){const r=engine.choose(id,state.preferences);if(r)recipeDialog(r.id);else showDialog(name(id),id,`<p>Este recurso no tiene una receta incluida en el catálogo estático. Consulta su obtención en JEI dentro del servidor.</p><button class="btn btn-primary" data-inventory-add="${esc(id)}">Añadir 1 a mis materiales</button>`);}
function plannerView(){const chosen=engine.byId.get(plannerRecipe)||engine.choose(plannerItem,state.preferences);if(chosen?.output.id!==plannerItem)plannerRecipe='';const r=engine.byId.get(plannerRecipe)||engine.choose(plannerItem,state.preferences);if(r)plannerRecipe=r.id;currentPlan=engine.plan(plannerItem,plannerQuantity,{inventory:state.inventory,preferences:state.preferences,selections:state.selections,rootRecipe:plannerRecipe,expand:plannerExpand});const plan=currentPlan;const outputs=[...engine.byOutput.keys()].sort((a,b)=>name(a).localeCompare(name(b),'es'));return pageTitle('PIENSA EN GRANDE. CALCULA PRIMERO.','Planos de fabricación','Elige qué quieres construir. Desglosa sus dependencias y calcula qué te falta con los materiales que ya tienes.',`<button class="btn btn-secondary" id="energy-calculator">⚙ Calcular estrés (SU)</button>`)+`<div class="panel"><div class="panel-body"><div class="planner-controls"><div class="field"><label for="plan-item">QUÉ VAMOS A FABRICAR</label><select id="plan-item">${outputs.map(id=>`<option value="${esc(id)}" ${id===plannerItem?'selected':''}>${esc(name(id))} · ${esc(id.split(':')[0])}</option>`).join('')}</select></div><div class="field"><label for="plan-qty">${r?.output.kind==='fluid'?'CANTIDAD (mB)':'CANTIDAD'}</label><input id="plan-qty" type="number" min="1" max="1000000" value="${plannerQuantity}"></div><button class="btn btn-primary" id="save-plan">Guardar plano ↗</button></div><div class="toolbar mt" style="margin-bottom:0"><div class="field" style="flex:1"><label for="plan-recipe">RECETA ELEGIDA</label><select id="plan-recipe" style="width:100%">${engine.candidates(plannerItem).map(r=>`<option value="${esc(r.id)}" ${r.id===plannerRecipe?'selected':''}>${esc(process(r.type))} · ${r.output.count} u. · ${esc(r.id)}</option>`).join('')}</select></div><label style="font-size:11px"><input id="plan-expand" type="checkbox" ${plannerExpand?'checked':''}> Desglosar subrecetas</label></div></div></div><div class="planner-summary"><span><b>${plan.processes.length}</b> operaciones desglosadas</span><span><b>${plan.leaves.length}</b> insumos por reunir</span><span><b>${Object.keys(plan.used).length}</b> materiales del inventario aplicados</span><span>Recortes y excedentes reutilizados</span></div>${plan.warnings.length?`<div class="note-box" style="margin-bottom:20px">${plan.warnings.map(esc).join('<br>')}</div>`:''}<div class="two-col"><section class="stack"><div><div class="section-heading"><h2>El plano</h2><span class="list-count">Entradas → objetivo</span></div><div class="tree-board"><ul class="tree root">${treeNode(plan.tree,true)}</ul></div></div><div class="panel"><div class="panel-header"><h3>Procesos e infraestructura</h3></div><div class="panel-body"><div class="phase-tags">${plan.machines.map(m=>`<span class="badge">${esc(process(m))}</span>`).join('')||'<p class="muted">El inventario ya cubre este objetivo.</p>'}</div><p class="server-note">Esta lista indica tipos de proceso, no cantidades de máquinas ni tasas de producción. Combustible, energía, herramientas, recipientes retornables y montaje se comprueban aparte.</p>${r?`<button class="btn btn-text mt" data-recipe="${esc(r.id)}">Ver receta del objetivo ↗</button>`:''}</div></div>${Object.keys(plan.assumptions).length?`<div class="panel"><div class="panel-header"><h3>Alternativas de materiales</h3></div><div class="panel-body"><p class="server-note" style="margin-top:0">Selecciones de este plano. Almost Unified puede resolver metales a otro mod dentro del juego.</p>${Object.entries(plan.assumptions).map(([tag,a])=>`<div class="field mt"><label for="tag-${esc(tag)}">#${esc(tag)}</label>${a.options.length?`<select id="tag-${esc(tag)}" data-tag-select="${esc(tag)}">${a.options.map(id=>`<option value="${esc(id)}" ${id===a.id?'selected':''}>${esc(name(id))} · ${esc(id)}</option>`).join('')}</select>`:`<p class="server-note">${a.unresolved?'Sin miembros verificables; se deja como insumo por resolver.':esc(name(a.id))+' · equivalencia propuesta, confirmar en JEI.'}</p>`}</div>`).join('')}</div></div>`:''}</section><section class="stack"><div class="panel"><div class="panel-header"><h3>Tu lista de materiales</h3><span class="badge gold">FALTANTES</span></div><div class="panel-body">${plan.leaves.length?`<div class="table-wrap"><table class="ingredients-list"><thead><tr><th>Material</th><th>Falta</th></tr></thead><tbody>${plan.leaves.sort((a,b)=>name(a.id).localeCompare(name(b.id))).map(l=>`<tr><td><div class="material-name">${icon(l.id)}<span>${esc(name(l.id))}<small class="muted">${l.id.startsWith('#')?'Alternativa por resolver':l.kind==='fluid'?'Fluido':Math.floor(l.count/64)+' stacks + '+(l.count%64)+'*'}</small></span></div></td><td>${fmt(l.count)}${l.kind==='fluid'?' mB':''}</td></tr>`).join('')}</tbody></table></div><p class="server-note">* Equivalencia de 64 unidades; algunos ítems tienen otro tamaño de stack. Los insumos sin subreceta pueden ser componentes ya elaborados.</p>`:'<p class="muted" style="font-size:12px">Tu inventario cubre el objetivo. Los materiales no se descuentan hasta que los edites.</p>'}<button class="btn btn-secondary" id="copy-materials">Copiar lista</button><button class="btn btn-text mt" data-view="inventory">Actualizar mis materiales →</button></div></div><div class="note-box"><strong>Elige la receta que ya puedes construir.</strong><br>El plano usa recetas básicas por defecto. No es un optimizador de recursos o velocidad. En las subrecetas puedes cambiar el proceso desde el selector inferior.</div><details class="panel"><summary class="panel-header" style="cursor:pointer;font-size:12px">Cambiar recetas intermedias</summary><div class="panel-body">${[...new Set(plan.processes.map(p=>p.recipe.output.id))].filter(i=>i!==plannerItem&&engine.candidates(i).length>1).slice(0,30).map(i=>`<div class="field mt"><label>${esc(name(i))}</label><select data-subrecipe="${esc(i)}" aria-label="Receta para ${esc(name(i))}">${engine.candidates(i).map(c=>`<option value="${esc(c.id)}" ${(state.preferences[i]||engine.choose(i)?.id)===c.id?'selected':''}>${esc(process(c.type))} · ${esc(c.id)}</option>`).join('')}</select></div>`).join('')||'<p class="server-note">No hay alternativas intermedias en este plano.</p>'}</div></details></section></div>`;}
function treeNode(n,root=false){return `<li><div class="tree-node ${root?'goal':''} ${n.raw?'raw':''}">${icon(n.id)}<div>${esc(name(n.id))}<small>${n.available?'✓ Cubierto con inventario / excedentes':n.recipe?`${n.batches} tanda${n.batches!==1?'s':''} · ${esc(process(n.type))}${n.estimated?' · estimación':''}`:n.kind==='fluid'?'Aportar fluido':n.id.startsWith('#')?'Alternativa por resolver':'Conseguir o preparar'}${n.stock?' · '+fmt(n.stock)+' en inventario':''}</small></div><span class="tree-qty">×${fmt(n.count)}</span></div>${n.children.length?`<ul class="tree">${n.children.map(c=>treeNode(c)).join('')}</ul>`:''}</li>`;}
function inventoryView(){const entries=Object.entries(state.inventory).filter(([,v])=>v>0).sort((a,b)=>name(a[0]).localeCompare(name(b[0])));return pageTitle('SABER QUÉ TIENES ES EL PRIMER PASO','Mis materiales','Registra tus reservas manualmente. Los planos las descuentan del cálculo sin consumirlas ni conectarse al servidor.')+`<form class="inventory-form" id="inventory-form"><input id="inventory-item" list="items-list" placeholder="Busca un recurso o escribe su ID (minecraft:iron_ingot)" required aria-label="Material a añadir"><input id="inventory-quantity" type="number" min="1" max="1000000" value="1" required aria-label="Cantidad a añadir"><button class="btn btn-primary" type="submit">Añadir material +</button><datalist id="items-list">${[...new Set([...engine.byOutput.keys(),...recipes.flatMap(r=>r.ingredients.filter(i=>i.kind==='item').map(i=>i.id))])].sort((a,b)=>name(a).localeCompare(name(b))).map(id=>`<option value="${esc(id)}">${esc(name(id))}</option>`).join('')}</datalist></form>${entries.length?`<div class="panel"><div class="table-wrap"><table class="ingredients-list"><thead><tr><th>Material</th><th>Identificador</th><th>Cantidad disponible</th><th></th></tr></thead><tbody>${entries.map(([id,qty])=>`<tr><td><div class="material-name">${icon(id)}${esc(name(id.replace(/^fluid:/,'')))}</div></td><td><small class="muted">${esc(id)}</small></td><td><input type="number" aria-label="Cantidad de ${esc(name(id))}" min="0" max="1000000" value="${qty}" data-inventory-edit="${esc(id)}"></td><td><button class="icon-button" data-inventory-remove="${esc(id)}" aria-label="Quitar ${esc(name(id))}">×</button></td></tr>`).join('')}</tbody></table></div></div>`:'<div class="empty-state"><h3>Tu almacén está por empezar.</h3><p>Añade tus primeros lingotes, madera o componentes.<br>Tu siguiente plano ya sabrá con qué cuentas.</p></div>'}<div class="note-box mt">Para fluidos usa el ID con prefijo <strong>fluid:</strong>, por ejemplo <strong>fluid:minecraft:water</strong>, y anota milibuckets (mB). Un cubo equivale a 1,000 mB.</div>`;}
function modsView(){let list=modScope==='addons'?addons:mods;const q=modQuery.toLowerCase();list=list.filter(m=>(m.name+' '+(m.modId||m.id)+' '+(addonNotes[m.modId]?.category||'')).toLowerCase().includes(q));return pageTitle('ELIGE LO QUE TU TALLER NECESITA','Un mundo de posibilidades',`Create y sus ${addons.length-1} addons e integraciones verificados, más el inventario del pack. Marca los que estás explorando para organizar tu partida.`)+`<div class="toolbar"><div class="tabs"><button class="tab ${modScope==='addons'?'active':''}" data-mod-scope="addons">Ecosistema Create</button><button class="tab ${modScope==='all'?'active':''}" data-mod-scope="all">Todo el modpack</button><button class="tab ${modScope==='addons'?`<div class="note-box" style="margin-bottom:20px">También incluye soporte técnico: ${report.technicalIntegrations.map(m=>esc(m.name)+' '+esc(m.version)).join(' · ')}. No añaden una ruta de fabricación propia.</div>`:modScope==='all'?'<p class="server-note" style="margin:0 0 18px">491 entradas del manifiesto: 487 mods y 4 shaders. Las versiones no corroboradas se dejan sin indicar.</p>':''}${modScope==='integrations'?'active':''}" data-mod-scope="integrations">Cómo conectarlos</button></div><input type="search" id="mod-search" value="${esc(modQuery)}" placeholder="Buscar un mod…" aria-label="Buscar mods"></div>${modScope==='addons'?`<div class="note-box" style="margin-bottom:20px">También incluye soporte técnico: ${report.technicalIntegrations.map(m=>esc(m.name)+' '+esc(m.version)).join(' · ')}. No añaden una ruta de fabricación propia.</div>`:modScope==='all'?'<p class="server-note" style="margin:0 0 18px">491 entradas del manifiesto: 487 mods y 4 shaders. Las versiones no corroboradas se dejan sin indicar.</p>':''}${modScope==='integrations'?`<div class="phase-grid">${pack.integrations.map(i=>`<article class="mod-card"><span class="eyebrow">${esc(i.from)} → ${esc(i.to)}</span><h3>${esc(i.use)}</h3><p>${esc(i.status)}</p><a href="${esc(i.source)}" target="_blank" rel="noopener noreferrer">Referencia del pack ↗</a></article>`).join('')}</div>`:`<p class="list-count" style="margin-bottom:14px">${list.length} entradas encontradas · ${Object.values(state.mods).filter(Boolean).length} marcados para explorar</p><div class="mod-grid">${list.map(m=>{const id=m.modId||m.id;const n=addonNotes[id];const url=m.url||(m.modrinthProject?'https://modrinth.com/mod/'+m.modrinthProject:m.projectUrl)||'https://www.curseforge.com/minecraft/modpacks/all-the-mods-10/files/8764211';return `<article class="mod-card"><div class="item-line"><span class="mod-initial">${esc(m.name.replace('Create: ','').replace('Create ','').slice(0,2).toUpperCase())}</span><div><h3>${esc(m.name)}</h3><small class="muted">${esc(m.version||'Versión fijada por el manifiesto')}</small></div></div>${n?`<p>${n.summary}</p><span class="badge muted" style="align-self:flex-start">${n.when}</span>`:`<p>${esc(id)}${m.fileId?' · Archivo '+esc(m.fileId):''}</p>`}<div class="mod-footer"><label class="check-inline"><input type="checkbox" data-mod-check="${esc(id)}" ${state.mods[id]?'checked':''}> Explorar</label><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Proyecto ↗</a></div>${n?`<button class="btn btn-small" data-addon-recipes="${esc(id)}">Ver recetas del addon</button>`:''}</article>`;}).join('')}</div>${!list.length?'<div class="empty-state">No hay mods con ese filtro.</div>':''}`}`;}
function notesView(){return pageTitle('QUE NINGUNA IDEA SE QUEDE ATRÁS','Mi bitácora','Guarda tus planos y anota lo que vas descubriendo. Exporta un respaldo para llevar tu taller a otro navegador.',`<span class="saved-label">${storageError?'Guardado local no disponible':'● Guardado en este navegador'}</span>`)+`<div class="two-col"><div class="panel"><div class="panel-header"><h3>Notas del ingeniero</h3></div><div class="panel-body"><textarea class="notes-area" id="personal-notes" placeholder="Coordenadas de mi taller, ideas para automatizar, pendientes del servidor…" aria-label="Mis notas">${esc(state.notes)}</textarea><p class="server-note">Se guarda mientras escribes. No se sincroniza con otras personas ni con tu servidor.</p></div></div><div class="panel"><div class="panel-header"><h3>Planos guardados</h3><span class="badge">${state.plans.length}</span></div><div class="panel-body">${state.plans.length?state.plans.map((p,i)=>`<div class="feature-row"><div style="flex:1"><h4>${esc(p.name)}</h4><p>${fmt(p.quantity)} × ${esc(name(p.item))}</p><button class="btn btn-text" data-open-plan="${i}">Abrir plano →</button></div><button class="icon-button" data-delete-plan="${i}" aria-label="Eliminar plano ${esc(p.name)}">×</button></div>`).join(''):'<p class="muted" style="font-size:12px">Tu primer plano aparecerá aquí.<br>Abre Planos de fabricación y pulsa Guardar plano.</p>'}</div></div></div><div class="panel mt"><div class="panel-body"><h3>Tu progreso viaja contigo</h3><p class="server-note">El respaldo incluye objetivos, materiales, notas, mods y planos. Importar combina el avance; las notas se conservan y los inventarios coincidentes toman el valor mayor.</p><div class="note-actions"><button class="btn btn-secondary" id="export-data">↓ Exportar respaldo</button><button class="btn" id="import-data">↑ Importar respaldo</button></div></div></div>`;}
function sourcesView(){return pageTitle('CONSTRUIR SOBRE DATOS CLAROS','Fuentes, versión y alcance','Investigado para tu partida en All the Mods 10 8.1. Aquí puedes comprobar de dónde sale la información y qué sigue dependiendo de tu servidor.')+`<div class="stats-grid"><div class="stat"><div class="stat-label">Modpack</div><div class="stat-value">8.1<small>ATM10</small></div></div><div class="stat"><div class="stat-label">Minecraft</div><div class="stat-value">1.21.1</div></div><div class="stat"><div class="stat-label">Create</div><div class="stat-value">6.0.10</div></div><div class="stat"><div class="stat-label">Recetas en el catálogo</div><div class="stat-value">${fmt(recipes.length)}</div></div></div><div class="note-box" style="margin-bottom:24px"><strong>Catálogo estático, progreso personal.</strong><br>Las recetas provienen de los JAR exactos de Minecraft, Create y sus addons, con modificaciones seleccionadas del ZIP oficial. No se ha iniciado el servidor para resolver todo KubeJS, Almost Unified, recetas dinámicas o cambios del administrador. Confirma en JEI cuando haya diferencias. La web no lee chunks, inventarios ni misiones del servidor.</div><div class="sources-list">${sources.map(s=>`<article class="source-item"><h3>${s.title}</h3><p>${s.description}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">Consultar fuente ↗</a></article>`).join('')}</div><div class="panel mt"><div class="panel-header"><h3>Qué incluye esta edición</h3></div><div class="panel-body"><p class="server-note" style="margin-top:0">8 etapas de Create con 40 objetivos; ${pack.routes.length} rutas complementarias; ${addons.length-1} addons e integraciones; catálogo estático con alternativas; planos con inventario y desglose recursivo; ruta de la ATM Star. Los objetivos y su orden son una síntesis editorial, no una importación de tu libro de misiones.</p><details class="disclosure mt"><summary>Límites de cálculo y verificación</summary><p>${pack.warnings.map(esc).join('<br>')}</p><p>El cálculo se detiene ante ciclos, fluidos, recetas ausentes o límites de complejidad; esos nodos quedan como insumos. Los excedentes deterministas se reutilizan y los resultados aleatorios son promedios. No calcula dimensiones de fábrica, combustible, velocidad, herramientas ni retornos de recipientes.</p></details><details class="disclosure"><summary>Créditos y archivos</summary><p>Minecraft pertenece a Mojang/Microsoft; Create y sus recursos pertenecen a sus autores. Los iconos se usan como referencia de sus objetos. Brassbound es una guía independiente sin afiliación. Arte del taller y diseño de esta web creados para esta bitácora.</p><a href="data/catalog-metadata.json" target="_blank" class="btn btn-text">Metadatos del catálogo ↗</a><br><a href="licenses/create-1.21.1-6.0.10/LICENSE.md_create-1.21.1" target="_blank" class="btn btn-text">Licencia de Create y sus recursos ↗</a></details></div></div>`;}
function energyDialog(){showDialog('¿Tiene fuerza tu taller?','CALCULADORA CINÉTICA · CREATE 6.0.10',`<p>Compara tu consumo con la capacidad de ruedas hidráulicas. Usa las RPM reales de cada máquina.</p><div class="gap-row mt"><div class="field" style="flex:1"><label for="energy-small">Ruedas pequeñas · 256 SU</label><input id="energy-small" type="number" min="0" max="1000" value="2"></div><div class="field" style="flex:1"><label for="energy-large">Ruedas grandes · 512 SU</label><input id="energy-large" type="number" min="0" max="1000" value="0"></div></div><div class="table-wrap mt"><table class="ingredients-list"><thead><tr><th>Máquina</th><th>Cantidad</th><th>RPM</th></tr></thead><tbody>${stress.machines.map((m,i)=>`<tr><td>${esc(name(m.id))}<small class="muted" style="display:block">${m.impact} SU por RPM</small></td><td><input id="energy-count-${i}" aria-label="Cantidad de ${esc(name(m.id))}" type="number" min="0" max="1000" value="${i===0?1:0}"></td><td><input id="energy-rpm-${i}" aria-label="RPM de ${esc(name(m.id))}" type="number" min="1" max="256" value="32"></td></tr>`).join('')}</tbody></table></div><button class="btn btn-primary" id="calculate-energy">Calcular capacidad</button><div id="energy-result" class="mt" role="status"></div><div class="note-box mt">${esc(stress.scope)} Las ruedas deben estar funcionando y conectadas a la misma red. Engranajes y controladores cambian RPM, no crean capacidad.</div><details class="disclosure"><summary>Planificar vapor</summary><p>Para una caldera activa y con agua continua: nivel = mínimo entre 18, tanques ÷ 4 redondeado hacia abajo, agua en mB/t ÷ 10 redondeado hacia abajo y nivel de calor. Un quemador calentado aporta 1; sobrecalentado, 2. Capacidad aprovechada = 16,384 × mínimo(motores, nivel). El régimen pasivo y el arranque se revisan aparte en Ponder.</p><a class="btn btn-text" target="_blank" rel="noopener noreferrer" href="${stress.sourceUrls[1]}">Fuente exacta del cálculo ↗</a></details>`);calculateEnergy();}
function calculateEnergy(){const cap=clampCount($('#energy-small').value)*256+clampCount($('#energy-large').value)*512;let demand=0;const warnings=[];stress.machines.forEach((m,i)=>{const count=clampCount($('#energy-count-'+i).value),rpm=clampCount($('#energy-rpm-'+i).value);demand+=count*rpm*m.impact;if(count&&(!rpm||rpm>256))warnings.push('Las RPM deben estar entre 1 y 256.');if(count&&m.id==='create:mechanical_mixer'&&rpm<32)warnings.push('El mezclador requiere al menos 32 RPM.');});$('#energy-result').innerHTML=`<div class="planner-summary"><span>Capacidad: <b>${fmt(cap)} SU</b></span><span>Consumo: <b>${fmt(demand)} SU</b></span></div><div class="note-box"><strong>${cap>=demand?'Margen disponible: '+fmt(cap-demand)+' SU':'Sobrecarga: faltan '+fmt(demand-cap)+' SU'}</strong>${warnings.length?'<br>'+[...new Set(warnings)].map(esc).join('<br>'):''}</div>`;}
function addInventory(id,n=1){state.inventory[id]=clampCount((state.inventory[id]||0)+n);save();toast(`${name(id)} añadido a tus materiales`);if(view==='inventory'||view==='planner')render();}
function download(filename,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function startPlan(id,recipe){plannerItem=id;plannerRecipe=recipe||'';$('#detail-dialog').close();navigate('planner');}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;
 if(d.view){e.preventDefault();$('#detail-dialog').close();navigate(d.view);}else if(d.phase)phaseDialog(d.phase);else if(d.packRoute)packRouteDialog(d.packRoute);else if(d.recipe)recipeDialog(d.recipe);else if(d.item)itemDialog(d.item);else if(d.plan)startPlan(d.plan,d.planRecipe);else if(d.close!==undefined)$('#detail-dialog').close();else if(d.routeScope){routeScope=d.routeScope;render();}else if(d.recipeScope){recipeScope=d.recipeScope;recipePage=0;render();}else if(d.page!==undefined){recipePage=Number(d.page);render();$('#recipe-results').scrollIntoView({block:'start'});}else if(d.modScope){modScope=d.modScope;render();}else if(d.addonRecipes){$('#detail-dialog').close();recipeMod=d.addonRecipes;recipeScope='create';recipeQuery='';recipePage=0;navigate('recipes');}else if(d.modDetail){const m=addons.find(m=>m.modId===d.modDetail);if(m){const n=addonNotes[m.modId];showDialog(m.name,'VERSIÓN '+m.version,`<p>${n.summary}</p><div class="note-box mt">Cuándo explorarlo: ${n.when}</div><button class="btn btn-primary" data-addon-recipes="${m.modId}">Explorar recetas ↗</button>`);}else{const r=pack.routes.find(r=>r.mods.includes(d.modDetail));if(r)packRouteDialog(r.id);else navigate('mods');}}else if(d.inventoryAdd)addInventory(d.inventoryAdd);else if(d.inventoryRemove){const old=state.inventory[d.inventoryRemove];delete state.inventory[d.inventoryRemove];save();render();toast('Material retirado del registro. Puedes volver a añadir '+old+' unidades.');}else if(d.openPlan!==undefined){const p=state.plans[Number(d.openPlan)];plannerQuantity=p.quantity;startPlan(p.item,p.recipe);}else if(d.deletePlan!==undefined){state.plans.splice(Number(d.deletePlan),1);save();render();toast('Plano retirado de la bitácora');}
 if(b.id==='global-search'){recipeScope='all';recipeQuery='';navigate('recipes');$('#recipe-search').focus();}if(b.id==='mobile-menu')$('.sidebar').classList.toggle('open');if(b.id==='save-plan'){showDialog('Ponle nombre a tu plano','GUARDAR EN MI BITÁCORA',`<form id="save-plan-form"><div class="field"><label for="plan-name">Nombre del plano</label><input id="plan-name" maxlength="120" value="${esc(plannerQuantity+' × '+name(plannerItem))}" required></div><button class="btn btn-primary" type="submit">Guardar plano</button></form>`);}if(b.id==='copy-materials'){const text=`Brassbound · ATM10 8.1\n${plannerQuantity} × ${name(plannerItem)}\n\nFaltantes:\n${currentPlan.leaves.map(l=>`${fmt(l.count)}${l.kind==='fluid'?' mB':''} × ${name(l.id)} [${l.id}]`).join('\n')}\n\n${currentPlan.warnings.join('\n')}\nCatálogo estático. Confirma en JEI del servidor.`;navigator.clipboard?.writeText(text).then(()=>toast('Lista copiada')).catch(()=>download('materiales-brassbound.txt',text,'text/plain'))||download('materiales-brassbound.txt',text,'text/plain');}if(b.id==='energy-calculator')energyDialog();if(b.id==='calculate-energy')calculateEnergy();if(b.id==='export-data')download('brassbound-atm10-8.1-respaldo.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2));if(b.id==='import-data')$('#import-file').click();
});
document.addEventListener('change',e=>{const el=e.target,d=el.dataset;if(d.task){state.tasks[d.task]=el.checked;save();el.closest('.check-item')?.classList.toggle('completed',el.checked);render();}if(d.modCheck){state.mods[d.modCheck]=el.checked;save();toast(el.checked?'Mod marcado para explorar':'Mod desmarcado');}if(d.inventoryEdit){state.inventory[d.inventoryEdit]=clampCount(el.value);save();render();}if(d.tagSelect){state.selections[d.tagSelect]=el.value;save();render();}if(d.subrecipe){state.preferences[d.subrecipe]=el.value;save();render();}if(el.id==='recipe-mod'){recipeMod=el.value;if(recipeScope==='featured')recipeScope='all';recipePage=0;render();}if(el.id==='plan-item'){plannerItem=el.value;plannerRecipe='';render();}if(el.id==='plan-qty'){plannerQuantity=Math.max(1,clampCount(el.value));render();}if(el.id==='plan-recipe'){plannerRecipe=el.value;state.preferences[plannerItem]=el.value;save();render();}if(el.id==='plan-expand'){plannerExpand=el.checked;render();}});
let searchTimer;document.addEventListener('input',e=>{const el=e.target;if(el.id==='personal-notes'){state.notes=el.value;save();}if(el.id==='recipe-search'||el.id==='mod-search'){const isRecipe=el.id==='recipe-search';const value=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(isRecipe){recipeQuery=value;recipePage=0;if(recipeQuery&&recipeScope==='featured')recipeScope='all';}else modQuery=value;const start=el.selectionStart;render();const input=$(isRecipe?'#recipe-search':'#mod-search');input.focus();try{input.setSelectionRange(start,start);}catch{}},180);}});
document.addEventListener('submit',e=>{if(e.target.id==='inventory-form'){e.preventDefault();let id=$('#inventory-item').value.trim();const qty=clampCount($('#inventory-quantity').value);if(!/^(fluid:)?[a-z0-9_.-]+:[a-z0-9_./-]+$/.test(id)){const match=[...engine.byOutput.keys()].find(x=>name(x).toLowerCase()===id.toLowerCase());if(match)id=match;else{toast('Selecciona un material o usa un ID como minecraft:iron_ingot');return;}}addInventory(id,qty);render();}if(e.target.id==='save-plan-form'){e.preventDefault();state.plans.push({item:plannerItem,quantity:plannerQuantity,recipe:plannerRecipe,name:$('#plan-name').value.trim()||name(plannerItem)});save();$('#detail-dialog').close();render();toast('Plano guardado en tu bitácora');}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('El respaldo es demasiado grande.');const imported=cleanState(JSON.parse(await file.text()));state.tasks={...state.tasks,...Object.fromEntries(Object.entries(imported.tasks).filter(([,v])=>v))};state.mods={...state.mods,...Object.fromEntries(Object.entries(imported.mods).filter(([,v])=>v))};for(const [id,n]of Object.entries(imported.inventory))state.inventory[id]=Math.max(state.inventory[id]||0,n);state.notes=state.notes===imported.notes?state.notes:[state.notes,imported.notes].filter(Boolean).join('\n\n--- Notas importadas ---\n\n');for(const p of imported.plans)if(!state.plans.some(x=>JSON.stringify(x)===JSON.stringify(p)))state.plans.push(p);state.preferences={...state.preferences,...imported.preferences};state.selections={...state.selections,...imported.selections};save();render();toast('Respaldo importado y combinado con tu progreso');}catch(err){toast(err.message||'No se pudo leer el respaldo');}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#detail-dialog').open){e.preventDefault();recipeScope='all';navigate('recipes');$('#recipe-search').focus();}});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
async function init(){try{const files=['recipes','translations','tags','icons','addons-exact','pack-guide','mods','report','stress'];const data=await Promise.all(files.map(f=>fetch(`data/${f}.json`).then(r=>{if(!r.ok)throw new Error('No se pudo cargar '+f);return r.json();})));[recipes,translations,tags,icons,addons,pack,mods,report,stress]=data;for(const r of pack.recipes){recipes.push({id:'atm-guide:'+r.id,type:'atm:'+r.machine,ingredients:r.ingredients.map(i=>({id:i.id.replace(/^#/,''),kind:i.kind==='tag'?'tag':(i.kind==='fluid'||i.kind==='mB')?'fluid':'item',count:i.quantity})),output:{id:r.outputItem,count:r.outputCount,chance:1},outputs:[{id:r.outputItem,count:r.outputCount,chance:1}],source:{modId:'atm10',version:'8.1',url:r.source,path:r.id},raw:r,warnings:[r.notes,r.verification].filter(Boolean),certainty:'atm-override'});}engine=createEngine(recipes,tags);navigate(location.hash.slice(1)||'home');}catch(err){$('#content').innerHTML=`<div class="empty-state"><h3>No se pudo abrir la bitácora.</h3><p>${esc(err.message)}</p><button class="btn mt" onclick="location.reload()">Volver a intentar</button></div>`;}}
init();
